solutions.naive:
class Solution:
    def productExceptSelf(self, nums: list[int]) -> list[int]:
        ans = []
        for i in range(len(nums)):
            prod = 1
            for j, x in enumerate(nums):
                if i != j:
                    prod *= x
            ans.append(prod)
        return ans

solutions.better:
class Solution:
    def productExceptSelf(self, nums: list[int]) -> list[int]:
        n = len(nums)
        pre = [1] * n
        suf = [1] * n
        for i in range(1, n):
            pre[i] = pre[i - 1] * nums[i - 1]
        for i in range(n - 2, -1, -1):
            suf[i] = suf[i + 1] * nums[i + 1]
        return [pre[i] * suf[i] for i in range(n)]

